import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·2","description":"易小帖 - 卷四·2","frontmatter":{"title":"卷四·2","description":"易小帖 - 卷四·2"},"headers":[],"relativePath":"classics/yixiaotie/096.md","filePath":"classics/yixiaotie/096.md"}'),o={name:"classics/yixiaotie/096.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·2",tabindex:"-1"},[r("卷四·2 "),e("a",{class:"header-anchor",href:"#卷四·2","aria-label":"Permalink to “卷四·2”"},"​")],-1),e("p",null,"蘇子瞻傳「先甲後甲」、「先庚後庚」世多稱之，但其說不可解。據雲：先甲三日，子戌申也，為陽盛陰生之時，治將生亂也。後甲三日，午辰寅也，為陰盛陽生之時，亂而後治也。所謂終則有始也。夫以庚甲十乾而忽以子醜十二枝當之已怪極矣，且陰陽往來，治亂循環。何卦不可雲而獨於蠱彖發之，有何理說？乃其於巽五則又雲：先庚三日，午辰寅也。寅盡於亥，先陰而後陽也。後庚三日，子戌申也，申盡於巳，先亂而治也。所謂無初有終也。則甲以子戌申為陰生為亂，而庚又以子戌申為後陽為治。甲以午辰寅為陽生為治，而庚又以午辰寅為先陰為亂。支離矛盾，吾所不解。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
